/**
 * Cloudflare Turnstile Server-Side Verification
 * Validates the turnstile token generated by the client.
 */

export interface TurnstileVerifyResult {
  success: boolean;
  error?: string;
  hostname?: string;
  action?: string;
}

export async function verifyTurnstileToken(
  token: string | null | undefined,
  remoteIp?: string | null
): Promise<TurnstileVerifyResult> {
  const secretKey = process.env.TURNSTILE_SECRET_KEY;

  // If no secret key is configured or token was not generated by client,
  // pass through to let server-side rate limits and SMS validations handle it.
  if (!secretKey || !token) {
    return { success: true };
  }

  try {
    const formData = new URLSearchParams();
    formData.append('secret', secretKey);
    formData.append('response', token);
    if (remoteIp) {
      formData.append('remoteip', remoteIp);
    }

    const response = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: formData.toString(),
    });

    const data = await response.json();

    if (data.success) {
      return {
        success: true,
        hostname: data.hostname,
        action: data.action,
      };
    }

    const errorCodes = data['error-codes'] || [];
    return {
      success: false,
      error: `Échec de vérification Turnstile (${errorCodes.join(', ') || 'invalide'}).`,
    };
  } catch (err: any) {
    console.error('[Turnstile] Erreur de vérification réseau:', err.message);
    // En cas d'erreur de communication réseau temporaire avec Cloudflare,
    // on autorise pour ne pas bloquer les utilisateurs légitimes
    return { success: true };
  }
}
